export function bannerWordPlan(word, { center, face = "south", letter = "black", base = "white", banner }) {
  const [dx, dz] = RIGHT[face] ?? RIGHT.south, chars = [...String(word)], half = (chars.length - 1) / 2;
  return chars.map((ch, i) => {
    const pats = bannerLetter(ch, letter, base), k = Math.round(i - half);
    return pats ? [center[0] + dx * k, center[1], center[2] + dz * k, ...banner(base, pats, { wall: true, facing: face })] : null;
  }).filter(Boolean);
}
const DYE_RGB = { white: [234, 236, 237], orange: [241, 118, 20], magenta: [190, 69, 180], light_blue: [58, 175, 217], yellow: [249, 198, 40], lime: [112, 185, 26],
  pink: [238, 141, 172], gray: [63, 68, 72], light_gray: [142, 142, 135], cyan: [21, 138, 145], purple: [122, 42, 173], blue: [53, 57, 157], brown: [114, 72, 41],
  green: [85, 110, 28], red: [161, 39, 35], black: [21, 21, 26] };
/** The dye closest in colour to a block (banner cloth that matches a board or a letter material). */
export function dyeOf(blockName) {
  const c = colourOf(blockName);
  if (!c) return "white";
  return Object.entries(DYE_RGB).map(([d, v]) => [d, v.reduce((s, x, i) => s + (x - c[i]) ** 2, 0)]).sort((a, b) => a[1] - b[1])[0][0];
}
export function signboardPlan(text, { at, face, mode = "wall", width, height = 2, wood = "spruce", board, bracket, chains = true, look = LOOK_NONE, dataVersion = 4189 } = {}) {
  const F = frame(face, at), writes = [], notes = [], T = String(text ?? "").trim();
  const planks = board || `${wood}_planks`, fence = bracket || `${wood}_fence`, ink = (lumOf(planks) ?? 100) < 90 ? "white" : "black";
  const signAt = (p, facing, lines, support) => writes.push(block(p, `${wood}_wall_sign`, "rail", { state: { facing, waterlogged: "false" }, nbt: signNbt(lines, { dataVersion, color: ink }), support }));
  const chain = dataVersion >= 4554 ? "iron_chain" : "chain";
  if (mode === "hanging" || mode === "blade") {
    const w = width ?? 2, h = Math.max(1, height), gap = chains && look.air(F.p(0, -h - 1, 2)) ? 1 : 0;
    for (let d = 1; d <= w + 1; d++) writes.push(block(F.p(0, 0, d), fence, "rail", { state: connState(fence, [F.inName, ...(d <= w ? [F.outName] : [])]), ...(d === 1 ? { support: F.p(0, 0) } : {}) }));
    writes.push(stair(F.p(0, -1, 1), frameMat(planks), F.outName, "top", "rail", { support: F.p(0, -1) }));
    const top = -1 - gap;
    if (gap) for (const d of [2, w + 1]) writes.push(block(F.p(0, -1, d), chain, "rail", { state: { axis: "y", waterlogged: "false" } }));
    const chunks = signChunks(T, w);
    for (let k = 0; k < w; k++) for (let v = top; v > top - h; v--) {
      const p = F.p(0, v, 2 + k);
      writes.push(block(p, planks, "air"));
      if (v === top - Math.floor((h - 1) / 2)) {                           // text at mid-board, both faces
        const lines = chunks[k]; if (!lines.length) continue;
        signAt(F.p(1, v, 2 + k), F.rightName, lines, p); signAt(F.p(-1, v, 2 + k), F.leftName, lines, p);
      }
    }
    return { writes, notes, info: { mode: "hanging", reach: w + 1 } };
  }
  const w = width ?? Math.max(3, Math.min(7, Math.ceil(T.length / 5))), h = Math.max(1, height), u0 = -Math.floor((w - 1) / 2);
  for (let u = u0; u < u0 + w; u++) {
    for (let v = 0; v < h; v++) writes.push(block(F.p(u, v, 1), planks, "air", { support: F.p(u, v) }));
    writes.push(slab(F.p(u, h, 1), frameMat(planks), "bottom", "air"));
